/**
 * Find the best (most specific) wiring diagram for a set of component IDs.
 * Uses a "contained-by" match: the diagram's component set must be a subset
 * of the cart's component set. The match with the most components wins.
 * Returns the mermaid filename or null if fewer than 2 components.
 */
export function findWiringDiagram(componentIds: string[]): string | null {
  const cartSet = new Set(componentIds);
  if (cartSet.size < 2) return null;

  let bestMatch: string | null = null;
  let bestLen = 0;

  for (const [ids, path] of WIRING_ENTRIES) {
    if (ids.length <= bestLen) continue; // Skip smaller matches
    const allPresent = ids.every(id => cartSet.has(id));
    if (allPresent) {
      bestLen = ids.length;
      bestMatch = path;
    }
  }

  return bestMatch;
}
